KG42.register("rules-0cc44f6458bf1e2b0c523c44",{"id":"02-dlmp::v141-c-R003","paper":"02-dlmp","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01","name":"Local market coordinator","process_stage":"coordination","market_meaning":"The DSO obtains the LMPs from the posted day-ahead energy prices. Scope: Step 1 of the proposed DLMP-based congestion-management procedure within electric distribution networks. The DSO forecasts expected EV demand according to EV data within the electric distribution network. Scope: Expected EV-demand forecasting in Step 2 of the proposed DLMP-based congestion-management procedure. Condition: All EV aggregators are assumed to minimize their EV charging costs. The DSO forecasts conventional demand according to the posted energy prices. Scope: Conventional-demand forecasting in Step 2 of the proposed DLMP-based congestion-management procedure.","independence_rationale":"Relations governed by the approved function coordination.local_operator under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.local_operator"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Conventional-demand forecasting in Step 2 of the proposed DLMP-based congestion-management procedure. | Expected EV-demand forecasting in Step 2 of the proposed DLMP-based congestion-management procedure. | Step 1 of the proposed DLMP-based congestion-management procedure within electric distribution networks.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E37"]},"x":[],"theta":[],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"The DSO obtains the LMPs from the posted day-ahead energy prices. Scope: Step 1 of the proposed DLMP-based congestion-management procedure within electric distribution networks.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E37"]},{"constraint_id":"v141-c-R003-C002","kind":"procedural","role":"core","statement":"The DSO forecasts expected EV demand according to EV data within the electric distribution network. Scope: Expected EV-demand forecasting in Step 2 of the proposed DLMP-based congestion-management procedure. Condition: All EV aggregators are assumed to minimize their EV charging costs.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E37"]},{"constraint_id":"v141-c-R003-C003","kind":"procedural","role":"core","statement":"The DSO forecasts conventional demand according to the posted energy prices. Scope: Conventional-demand forecasting in Step 2 of the proposed DLMP-based congestion-management procedure.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E37"]}],"pi":[{"evidence_id":"v141-b-g01-E37","location":{"location_id":"src-16569f9a14-p05-c2r3__v141-a-M01-coordination","page":5,"printed_page":"207","section":"IV. Alleviating Congestion From EVs Within Electric Distribution Networks Using DLMP","anchor_text":"caused by the EV charging demand. The congestion alleviation 2) approach using DLMP is illustrated i","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"unknown"},"source_text":"The DSO plays a major role in the DLMP-based congestion management within electric distribution networks. The concept can be explained by the following steps.\nStep 1) The DSO obtains the LMPs from the posted day-ahead energy prices.\nStep 2) According to the EV data within the electric distribution network, the expected EV demand will be forecasted by the DSO with the assumption that all EV aggregators are minimizing their EV charging costs. Conventional demand will be forecasted by the DSO according to the posted energy prices.\nStep 3) With the information on the forecasted demand, the DSO calculates the DLMPs at the electric distribution network level taking into account the electric distribution network topology.\nStep 4) In the end, the DLMPs will be sent to all EV aggregators and retailers."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":"The scoped candidate source E37 for R003 is a DSO operating procedure: obtain posted day-ahead LMPs and forecast EV and conventional demand. It defines no decision variable selected by an optimization or market participant within this rule. Charging decisions such as x_{i,t} and the aggregator problem appear in other rules/evidence and must not be moved into this rule without a C.1 graph revision.","empty_theta_reason":"The scoped candidate source E37 references external inputs (posted day-ahead energy prices, LMPs, EV data, electric distribution network topology) only procedurally; it does not define them as fixed constants or parameters with numeric values, units, or domains in this rule. The frozen R003 graph declares no theta, and no missing parameter values or meanings are inferred."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-coordination"],"extras":{"decision_anchor":"coordination.local_operator","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E37","quote":"Step 1) The DSO obtains the LMPs from the posted day-ahead energy prices."}],[{"evidence_id":"v141-b-g01-E37","quote":"Step 2) According to the EV data within the electric distribution network, the expected EV demand will be forecasted by the DSO with the assumption that all EV aggregators are minimizing their EV charging costs."}],[{"evidence_id":"v141-b-g01-E37","quote":"Conventional demand will be forecasted by the DSO according to the posted energy prices."}]],"C2_formalization":{"graph_sha256":"59a22b0abfdd2af9d12116ecfaeebb5dde06d469ca9c02d7776af8361c19a27f","applicability":"non_mathematical","reason":"R003 is a procedural coordination rule scoped by candidate evidence E37 to the DSO's operating steps of obtaining posted day-ahead LMPs and forecasting EV and conventional demand. The frozen graph contains only the node coordination.local_operator and no x, theta, equations, or edges; the three phi entries are operational steps, so the supported classification is non_mathematical rather than formalized. The B evidence is unreviewed in this experiment and this output makes no claim of independent source verification.","bindings":[{"object_id":"v141-c-R003-C001","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"C001 assigns a coordination action to the DSO, represented by the frozen node coordination.local_operator. The frozen R003 graph supplies no edge for this procedural step."},{"object_id":"v141-c-R003-C002","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"C002 assigns the DSO's EV-demand forecasting action under the stated EV-aggregator cost-minimization assumption to the frozen node coordination.local_operator. The frozen R003 graph supplies no edge for this procedural step."},{"object_id":"v141-c-R003-C003","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"C003 assigns the DSO's conventional-demand forecasting action to the frozen node coordination.local_operator. The frozen R003 graph supplies no edge for this procedural step."}],"revision_requests":[]}},"quarantined_references":[]}});
